import json
from confluent_kafka import Consumer

consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "billing",
    "auto.offset.reset": "earliest",       # new group: start from the oldest record
})
consumer.subscribe(["orders"])

try:
    while True:
        msg = consumer.poll(1.0)
        if msg is None:
            continue                        # nothing within 1 s
        if msg.error():
            print("error:", msg.error())
            continue
        event = json.loads(msg.value())
        print(msg.partition(), msg.offset(), msg.key().decode(), event["status"])
        # 1 0 c1 created
except KeyboardInterrupt:
    pass
finally:
    consumer.close()                        # commit and leave the group cleanly

from confluent_kafka import Producer

# match the Java client's murmur2 hashing so keys map to the same partitions
producer = Producer({
    "bootstrap.servers": "localhost:9092",
    "partitioner": "murmur2_random",    # librdkafka default: consistent_random
})

placed = {}
def remember(err, msg):
    placed.setdefault(msg.key().decode(), set()).add(msg.partition())

for i in range(30):
    producer.produce("orders", key=f"c{i % 3}", value=str(i), on_delivery=remember)
producer.flush()
print(placed)    # each key appears in exactly one partition, e.g.
# {'c0': {2}, 'c1': {0}, 'c2': {2}}

from confluent_kafka import Consumer

def handle(msg):
    print("processed", msg.offset())     # e.g. write to a database (idempotently)

consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "billing",
    "enable.auto.commit": False,         # we decide when work is done
    "auto.offset.reset": "earliest",
})
consumer.subscribe(["orders"])
done = 0
try:
    while done < 1000:
        msg = consumer.poll(1.0)
        if msg is None or msg.error():
            continue
        handle(msg)                       # 1. process
        done += 1
        if done % 100 == 0:
            consumer.commit(asynchronous=False)   # 2. commit current positions
finally:
    consumer.commit(asynchronous=False)   # 3. final commit on shutdown
    consumer.close()

import java.util.Properties;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;

public class OrderCounts {
    public static void main(String[] args) {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "order-counts");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.StringSerde.class);
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.StringSerde.class);

        StreamsBuilder builder = new StreamsBuilder();
        KStream<String, String> orders = builder.stream("orders");   // key = customer
        KTable<String, Long> counts = orders.groupByKey().count();   // state store + changelog
        counts.toStream().to("orders-per-customer", Produced.with(Serdes.String(), Serdes.Long()));

        KafkaStreams app = new KafkaStreams(builder.build(), props);
        Runtime.getRuntime().addShutdownHook(new Thread(app::close));
        app.start();
    }
}
